head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDSTF60003";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf60003.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "cal_strDt", fn: function () { return String((dma_pageContext.get("strDt") ?? "")); } },
        { childId: "cal_endDt", fn: function () { return String((dma_pageContext.get("endDt") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_41_onclick
 * @description 「화남」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_41_onclick = async function(e){
    try {
        await scwin.dsclSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf60003.img_41_onclick' }); }
};

/**
 * @method
 * @name img_292_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_292_onclick = async function(e){
    try {
        await scwin.preView()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf60003.img_292_onclick' }); }
};

/**
 * @method
 * @name img_294_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_294_onclick = async function(e){
    try {
        await scwin.excel('' + dma_pageContext.get("strDt") + '','' + dma_pageContext.get("endDt") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf60003.img_294_onclick' }); }
};

/**
 * @method
 * @name img_296_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_296_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf60003.img_296_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_preView
 * @description pre View 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_preView = async function () {
    const sbmOptions = {
        id: "tx_fn_preView",
        method: "post",
        action: "/DscltrendInfo.do?method=dsclTrendPreView",
        ref: "dma_preViewReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_dsclSearch
 * @description dscl Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_dsclSearch = async function () {
    const sbmOptions = {
        id: "tx_fn_dsclSearch",
        method: "post",
        action: "/DscltrendInfo.do",
        ref: "dma_dsclSearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_excel
 * @description excel 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_excel = async function (action) {
    try { return await $c.data.downFile(action ?? "/DscltrendInfo.do?method=dsclTrendExcel&str_dt=", "", ($c.util.getComponent("dma_excelReq") ? $c.util.getComponent("dma_excelReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name preView
 * @description pre View 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.preView = async function () {
    const f = (document.form || { elements: [] });
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/DscltrendInfo.do?method=dsclTrendPreView", unresolved: "nav:" + "/DscltrendInfo.do?method=dsclTrendPreView" }; })();

    f.action = "/DscltrendInfo.do?method=dsclTrendPreView";
    $c.util.getComponent('dma_preViewReq').set('SCREN_PROCES_TP_CD', "06");
    f.target = '';
    f.action = '';
};

/**
 * @method
 * @name excel
 * @description excel 처리
 * @param {*} str_dt str_dt
 * @param {*} end_dt end_dt
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excel = async function (str_dt, end_dt) {
    $c.util.getComponent('dma_preViewReq').set('SCREN_PROCES_TP_CD', "07");
    await scwin.tx_fn_excel("/DscltrendInfo.do?method=dsclTrendExcel&str_dt=" + str_dt + "&end_dt=" + end_dt);
};

/**
 * @method
 * @name dsclSearch
 * @description dscl Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dsclSearch = async function () {
    $c.util.getComponent('dma_preViewReq').set('method', "dsclTrendView");
    $c.util.getComponent('dma_preViewReq').set('SCREN_PROCES_TP_CD', "01");
    await scwin.tx_fn_dsclSearch();
};
